//! 导出分辨率预设: 只选高度, 宽度与画幅跟随 `game/config.txt` 的舞台尺寸。

use std::path::PathBuf;

use webgal_video_export::api::{ExportOptions, build_plan, output_width};

fn fixture() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/minimal")
}

fn plan_for_height(height: u32) -> webgal_video_export::plan::Plan {
    let mut options = ExportOptions::new(fixture());
    options.config.video.auto_width = true;
    options.config.video.height = height;
    build_plan(&options).expect("build plan")
}

#[test]
fn presets_follow_the_stage_aspect_ratio() {
    // fixture 的 config.txt 没有 Stage_Width/Height, 使用 WebGAL 默认 2560×1440 (16:9)。
    for (height, width) in [(720, 1280), (1080, 1920), (1440, 2560), (2160, 3840)] {
        let plan = plan_for_height(height);
        assert_eq!(
            (plan.meta.output_w, plan.meta.output_h),
            (width, height),
            "{height}p 的输出尺寸"
        );
        assert_eq!(
            (plan.meta.stage_w, plan.meta.stage_h),
            (width, height),
            "舞台坐标随输出一起缩放"
        );
    }
}

#[test]
fn positions_scale_with_the_output_size() {
    // fixture: `-left` 基准 -430, setTransform 再偏移 200 → 绝对 -230 (2560 坐标)。
    // 720p 时缩放系数 1280/2560 = 0.5, 关键帧位置应为 -115。
    let plan = plan_for_height(720);
    let track = plan
        .figures
        .iter()
        .find(|track| track.id == "fig-left")
        .expect("fig-left");
    let transform = track.keys.last().expect("transform key");
    let x = transform
        .transform
        .position
        .and_then(|position| position.x)
        .expect("position.x");
    assert_eq!(x, -115);
}

#[test]
fn widths_are_even() {
    // H.264 的 yuv420p 要求偶数宽。
    assert_eq!(output_width(1080, 1000, 1000), 1080);
    assert_eq!(output_width(1079, 1000, 1000), 1078);
    assert_eq!(output_width(720, 2560, 1440), 1280);
    assert_eq!(output_width(0, 2560, 1440), 0);
}
